#!/usr/bin/env bash
# Build the windows gauntlet's harness: gauntlet.c's hand-written C and the
# LLVM IR the windows target printed for the gauntlet's programs, each compiled
# by the same clang at the target's own -O2 (the build every windows program
# gets, emit/target.go's build.bat), and linked into one bench.exe.
#
#   bash gauntlet/windows/bench-build.sh OUT [LLDIR]
#
# LLDIR holds the gen_*.ll files (default gauntlet/windows, regenerated by
# gauntlet/regen.sh and compared by cmd/check); OUT receives the objects,
# bench.exe, and the inputs and Go's answers (gauntlet/go/wininputs). Then
#
#   OUT/bench.exe OUT check       every case against Go's answers
#   OUT/bench.exe OUT CASE        one case timed, after the check
set -euo pipefail
cd "$(dirname "$0")/../.."
out=$1
ll=${2:-gauntlet/windows}
clang="${LOCALAPPDATA:-}/Programs/LLVM/bin/clang.exe"
[ -x "$clang" ] || clang=clang
mkdir -p "$out"
w() { cygpath -w "$1" 2>/dev/null || echo "$1"; }
(cd gauntlet/go && go run ./wininputs "$(w "$out")")
objs=()
for f in "$ll"/gen_*.ll; do
  o="$out/$(basename "${f%.ll}").obj"
  "$clang" -O2 -Wno-override-module -c -o "$(w "$o")" "$(w "$f")"
  objs+=("$(w "$o")")
done
"$clang" -O2 -c -o "$(w "$out/harness.obj")" "$(w gauntlet/windows/gauntlet.c)"
"$clang" -fuse-ld=lld -o "$(w "$out/bench.exe")" "$(w "$out/harness.obj")" "${objs[@]}" -lkernel32
"$out/bench.exe" "$(w "$out")" check
